# idea: champion + 16D fine-grained function-word category (articles/pronouns/preps/aux/conj detected via char matching)
"""
Adds explicit detection of the ~50 most common English function words via character
pattern matching (not pretrained!). Groups into 12 syntactic categories: articles,
personal-pronouns, object-pronouns, prepositions, auxiliaries, conjunctions, modals,
determiners, adverbs, negation, wh-words, other-function. The champion only has binary
is_function (len≤3); this provides FINE-GRAINED category that ridge can use to predict
category-specific high-gamma patterns. Only +16D but extremely high signal.
"""
import torch
import numpy as np

SEQ_LEN = 96
SPACE_ID = 2

D_TRIG_HASH = 2048
D_CTX_HASH = 1024
D_CTX_SHARP = 512
D_CTX_VSHARP = 256
D_EMBED = 192
D_DENSE = 165
D_TRANS = 128  # abstract transition types
D_SYNCAT = 48  # syntactic category: trigger (16) + prev (16) + category-pair transition (16)
# Total: ~4501

VOWELS = {3, 8, 12, 18, 24, 28}
CONSONANTS = set(range(3, 29)) - VOWELS
GAMMA = 0.95

# Function word detection via character codes (3=a, 4=b, ..., 28=z)
# Encode common function words as tuples of char IDs
def _encode_word(s):
    return tuple(ord(c) - ord('a') + 3 for c in s)

# 12 syntactic categories
SYNCAT_WORDS = {
    0: ['the', 'a', 'an'],  # articles
    1: ['i', 'you', 'he', 'she', 'it', 'we', 'they'],  # subject pronouns
    2: ['me', 'him', 'her', 'us', 'them', 'my', 'his', 'your', 'our', 'their'],  # obj/poss pronouns
    3: ['to', 'of', 'in', 'for', 'on', 'at', 'by', 'with', 'from', 'about', 'into'],  # prepositions
    4: ['is', 'was', 'are', 'were', 'be', 'been', 'am', 'has', 'had', 'have', 'do', 'did', 'does'],  # aux
    5: ['and', 'or', 'but', 'so', 'if', 'when', 'while', 'because', 'that', 'which'],  # conj/relative
    6: ['can', 'could', 'would', 'should', 'will', 'may', 'might', 'must'],  # modals
    7: ['this', 'that', 'these', 'those', 'some', 'any', 'all', 'each', 'every'],  # determiners
    8: ['not', 'no', 'never', 'neither', 'nor'],  # negation
    9: ['very', 'just', 'also', 'still', 'even', 'only', 'really', 'quite'],  # adverbs
    10: ['what', 'who', 'how', 'where', 'why', 'which', 'whom'],  # wh-words
    11: ['there', 'here', 'then', 'now', 'up', 'out', 'down', 'back'],  # deictic/particles
}
# Build lookup: encoded_word_tuple -> category_index
SYNCAT_LOOKUP = {}
for cat_idx, word_list in SYNCAT_WORDS.items():
    for w in word_list:
        SYNCAT_LOOKUP[_encode_word(w)] = cat_idx

np.random.seed(123)
CHAR_EMBEDS = np.random.randn(60, 32).astype(np.float32) * 0.5

# Bilinear interaction: random projections for trigger and context banks
np.random.seed(321)
D_BILINEAR = 64
# Orthogonal random projections via QR decomposition
_trig_raw = np.random.randn(2048, D_BILINEAR).astype(np.float32)
PROJ_TRIG, _ = np.linalg.qr(_trig_raw)  # (2048, 64) with orthonormal columns
PROJ_TRIG = (PROJ_TRIG / np.sqrt(2048)).astype(np.float32)
_ctx_raw = np.random.randn(1024, D_BILINEAR).astype(np.float32)
PROJ_CTX, _ = np.linalg.qr(_ctx_raw)  # (1024, 64)
PROJ_CTX = (PROJ_CTX / np.sqrt(1024)).astype(np.float32)

N_EMBED_PARAMS = 60 * 32 + 2048 * D_BILINEAR + 1024 * D_BILINEAR  # char_embeds + projections


def _hash_ngrams(chars, n, n_buckets):
    counts = np.zeros(n_buckets, dtype=np.float32)
    for i in range(len(chars) - n + 1):
        h = 0
        for j in range(n):
            h = h * 31 + int(chars[i + j])
        counts[h % n_buckets] += 1.0
    return counts


def _word_hash(chars, n_buckets, n_hashes=6):
    vec = np.zeros(n_buckets, dtype=np.float32)
    for seed in range(n_hashes):
        h = seed * 7919
        for c in chars:
            h = (h * 31 + int(c)) & 0x7FFFFFFF
        bucket = h % n_buckets
        sign_h = (h * 2654435761) & 0x7FFFFFFF
        sign = 1.0 if (sign_h % 2) == 0 else -1.0
        vec[bucket] += sign
    return vec


def _word_type(word):
    """Classify word into abstract type: 0=short-function, 1=medium, 2=long-content"""
    wlen = len(word)
    if wlen <= 3:
        return 0  # function-like
    elif wlen <= 6:
        return 1  # medium
    else:
        return 2  # long content


def _onset_type(word):
    """First char type: 0=vowel, 1=consonant, 2=other"""
    if not word:
        return 2
    if word[0] in VOWELS:
        return 0
    elif word[0] in CONSONANTS:
        return 1
    return 2


def _coda_type(word):
    """Last char type: 0=vowel, 1=consonant, 2=other"""
    if not word:
        return 2
    if word[-1] in VOWELS:
        return 0
    elif word[-1] in CONSONANTS:
        return 1
    return 2


def _transition_hash(prev_word, next_word, n_buckets, n_hashes=4):
    """Hash abstract transition properties between two words."""
    vec = np.zeros(n_buckets, dtype=np.float32)
    if not prev_word or not next_word:
        return vec

    # Build a transition descriptor from abstract properties
    wt_prev = _word_type(prev_word)
    wt_next = _word_type(next_word)
    onset_next = _onset_type(next_word)
    coda_prev = _coda_type(prev_word)

    # Length ratio bin (0-4)
    len_ratio = len(next_word) / (len(prev_word) + 1e-8)
    ratio_bin = min(int(len_ratio * 2), 4)

    # Shared suffix (do they rhyme?)
    shared_end = 0
    for k in range(1, min(len(prev_word), len(next_word)) + 1):
        if prev_word[-k] == next_word[-k]:
            shared_end = k
        else:
            break

    # Hash multiple transition "features" into the bank
    features = [
        (wt_prev, wt_next),                    # type transition
        (coda_prev, onset_next),               # boundary phonotactic
        (wt_prev, onset_next),                 # type -> onset
        (coda_prev, wt_next),                  # coda -> type
        (ratio_bin, wt_next),                  # length ratio + type
        (wt_prev, wt_next, coda_prev, onset_next),  # full 4-way
        (min(shared_end, 3), wt_next),         # rhyme + type
        (len(prev_word) % 4, len(next_word) % 4),  # length mod pattern
    ]

    for feat_idx, feat in enumerate(features):
        for seed in range(n_hashes):
            h = seed * 7919 + feat_idx * 104729
            for v in feat:
                h = (h * 31 + int(v)) & 0x7FFFFFFF
            bucket = h % n_buckets
            sign_h = (h * 2654435761) & 0x7FFFFFFF
            sign = 1.0 if (sign_h % 2) == 0 else -1.0
            vec[bucket] += sign

    return vec


def _shared_chars(w1, w2):
    s1 = set(int(c) for c in w1)
    s2 = set(int(c) for c in w2)
    if not s1 or not s2:
        return 0.0
    return len(s1 & s2) / len(s1 | s2)


def _shared_bigrams(w1, w2):
    if len(w1) < 2 or len(w2) < 2:
        return 0.0
    b1 = set((int(w1[i]), int(w1[i+1])) for i in range(len(w1)-1))
    b2 = set((int(w2[i]), int(w2[i+1])) for i in range(len(w2)-1))
    return len(b1 & b2) / (max(len(b1), len(b2)) + 1e-8)


class Model:
    name = "syncat-infoweight-champion"
    idea = "0.0626 champion with informativeness-weighted context (content words 1.3x in context bag)"
    description = (
        "Modifies context bag weighting: content words (not in syncat lookup AND len>3) get 1.3x "
        "extra weight in the recency bag. Function words that appear constantly contribute noise "
        "to the context representation; content words carry TOPIC information that might help "
        "predict what kind of word comes next."
    )
    insight = (
        "The context bag weights all words equally (modulo recency). But function words like "
        "'the', 'is', 'in' appear every few words and their hash patterns dominate the bag, "
        "diluting the TOPIC-CARRYING content words. Boosting content words by 1.3x gives ridge "
        "better access to the topic context, which might predict whether the trigger is a "
        "topic-continuation (lower HG) or topic-switch (higher HG) word."
    )
    n_params = N_EMBED_PARAMS

    @torch.no_grad()
    def __call__(self, X):
        X = torch.as_tensor(X, dtype=torch.long)
        N, L = X.shape
        device = X.device
        X_np = X.cpu().numpy()

        out_trig = np.zeros((N, D_TRIG_HASH), dtype=np.float32)
        out_ctx = np.zeros((N, D_CTX_HASH), dtype=np.float32)
        out_ctx_sharp = np.zeros((N, D_CTX_SHARP), dtype=np.float32)
        out_ctx_vs = np.zeros((N, D_CTX_VSHARP), dtype=np.float32)
        out_embed = np.zeros((N, D_EMBED), dtype=np.float32)
        out_dense = np.zeros((N, D_DENSE), dtype=np.float32)
        out_trans = np.zeros((N, D_TRANS), dtype=np.float32)
        out_syncat = np.zeros((N, D_SYNCAT), dtype=np.float32)

        for i in range(N):
            seq = X_np[i]
            nonpad = seq[seq > 0]
            if len(nonpad) == 0:
                continue

            words = []
            current = []
            for c in nonpad:
                if c == SPACE_ID:
                    if current:
                        words.append(current)
                        current = []
                else:
                    current.append(int(c))
            if current:
                words.append(current)
            if not words:
                continue

            trigger = words[-1]
            trig_len = len(trigger)
            n_words = len(words)

            # --- Trigger hash (proven) ---
            for n in [2, 3, 4]:
                out_trig[i] += _hash_ngrams(trigger, n, D_TRIG_HASH)
            for c in trigger:
                out_trig[i][int(c) % D_TRIG_HASH] += 1.0

            # --- Context hash (proven) with informativeness weighting ---
            for j, word in enumerate(words[:-1]):
                dist = n_words - 1 - j
                weight = GAMMA ** dist
                # Content words get extra weight (they're more informative/topic-specific)
                word_key = tuple(word)
                if SYNCAT_LOOKUP.get(word_key, -1) < 0 and len(word) > 3:
                    weight *= 1.3  # boost content words
                out_ctx[i] += weight * _word_hash(word, D_CTX_HASH)
            out_ctx[i] += 3.5 * _word_hash(trigger, D_CTX_HASH)
            if n_words >= 2:
                pair = words[-2] + [99] + trigger
                out_ctx[i] += 2.5 * _word_hash(pair, D_CTX_HASH)

            # --- Sharp recency context (gamma=0.7) ---
            for j, word in enumerate(words[:-1]):
                dist = n_words - 1 - j
                weight = 0.7 ** dist
                out_ctx_sharp[i] += weight * _word_hash(word, D_CTX_SHARP)

            # --- Very sharp prev-word bank ---
            if n_words >= 2:
                out_ctx_vs[i] += 3.0 * _word_hash(words[-2], D_CTX_VSHARP)
            if n_words >= 3:
                out_ctx_vs[i] += 1.0 * _word_hash(words[-3], D_CTX_VSHARP)
            out_ctx_vs[i] += 2.0 * _word_hash(trigger, D_CTX_VSHARP)

            # --- NEW: Abstract transition type bank ---
            for j in range(1, n_words):
                dist_from_end = n_words - 1 - j
                weight = 0.85 ** dist_from_end
                out_trans[i] += weight * _transition_hash(words[j-1], words[j], D_TRANS)
            # Extra weight on trigger boundary
            if n_words >= 2:
                out_trans[i] += 2.0 * _transition_hash(words[-2], trigger, D_TRANS)

            # --- Syntactic category detection ---
            trig_key = tuple(trigger)
            cat = SYNCAT_LOOKUP.get(trig_key, -1)
            if cat >= 0:
                out_syncat[i, cat] = 1.0
            # Previous word category (offset by 16)
            prev_cat = -1
            if n_words >= 2:
                prev_key = tuple(words[-2])
                prev_cat = SYNCAT_LOOKUP.get(prev_key, -1)
                if prev_cat >= 0:
                    out_syncat[i, 16 + prev_cat] = 1.0
            # Category transition pair: hash(prev_cat, trig_cat) into 16 buckets
            # This captures syntactic bigram patterns (prep→noun, det→noun, aux→verb, etc.)
            trig_cat_eff = cat if cat >= 0 else 12  # 12 = content word
            prev_cat_eff = prev_cat if prev_cat >= 0 else 12
            pair_hash = (prev_cat_eff * 13 + trig_cat_eff) & 0x7FFFFFFF
            pair_bucket = pair_hash % 16
            out_syncat[i, 32 + pair_bucket] = 1.0
            # Content word with suffix subcategory
            if cat < 0:
                # Approximate subcategory by suffix
                if trig_len >= 3:
                    last2 = (trigger[-2], trigger[-1])
                    # -ing
                    if last2 == (12, 9) and trig_len >= 4 and trigger[-3] == 16:
                        out_syncat[i, 12] = 1.0
                    # -ed
                    elif last2 == (7, 6):
                        out_syncat[i, 13] = 1.0
                    # -ly
                    elif last2 == (14, 27):
                        out_syncat[i, 14] = 1.0
                    # -tion/-sion
                    elif trig_len >= 4 and trigger[-1] == 16 and trigger[-2] == 18 and trigger[-3] == 12:
                        out_syncat[i, 15] = 1.0  # -ion
                    # -ness
                    elif trig_len >= 4 and last2 == (21, 21) and trigger[-3] == 7 and trigger[-4] == 16:
                        pass  # skip complex suffix detection to avoid bugs

            # --- Random char embedding pooling ---
            if trig_len > 0:
                embeds = np.array([CHAR_EMBEDS[min(c, 59)] for c in trigger])
                trig_mean = embeds.mean(axis=0)
                out_embed[i, :32] = trig_mean
                out_embed[i, 32:64] = embeds.max(axis=0)
                pos_weights = np.arange(1, trig_len + 1, dtype=np.float32) / trig_len
                out_embed[i, 64:96] = (embeds * pos_weights[:, None]).sum(axis=0) / pos_weights.sum()
                if n_words >= 2:
                    prev = words[-2]
                    prev_embeds = np.array([CHAR_EMBEDS[min(c, 59)] for c in prev])
                    prev_mean = prev_embeds.mean(axis=0)
                    out_embed[i, 96:128] = trig_mean - prev_mean
                    out_embed[i, 128:160] = trig_mean * prev_mean
                if n_words >= 3:
                    prev2 = words[-3]
                    prev2_embeds = np.array([CHAR_EMBEDS[min(c, 59)] for c in prev2])
                    prev2_mean = prev2_embeds.mean(axis=0)
                    out_embed[i, 160:192] = trig_mean - prev2_mean

            # --- Dense features (exact champion copy) ---
            f = 0
            trig_len_norm = trig_len / 15.0
            out_dense[i, f] = trig_len_norm; f += 1
            out_dense[i, f] = np.log1p(trig_len) / 3.0; f += 1

            in_vowel = False; syllables = 0
            for c in trigger:
                if c in VOWELS:
                    if not in_vowel: syllables += 1; in_vowel = True
                else: in_vowel = False
            syl_norm = syllables / 5.0
            out_dense[i, f] = syl_norm; f += 1

            n_vowels = sum(1 for c in trigger if c in VOWELS)
            n_cons = sum(1 for c in trigger if c in CONSONANTS)
            vowel_ratio = n_vowels / (trig_len + 1e-8)
            cons_ratio = n_cons / (trig_len + 1e-8)
            out_dense[i, f] = vowel_ratio; f += 1
            out_dense[i, f] = cons_ratio; f += 1

            max_cluster = 0; cluster = 0
            for c in trigger:
                if c in CONSONANTS: cluster += 1; max_cluster = max(max_cluster, cluster)
                else: cluster = 0
            cluster_norm = max_cluster / 4.0
            out_dense[i, f] = cluster_norm; f += 1

            wc_norm = n_words / 11.0
            out_dense[i, f] = wc_norm; f += 1
            seq_fill = len(nonpad) / SEQ_LEN
            out_dense[i, f] = seq_fill; f += 1
            is_function = 1.0 if trig_len <= 3 else 0.0
            out_dense[i, f] = is_function; f += 1

            ctx_mean_len = 0.0; ctx_std_len = 0.0
            if n_words > 1:
                ctx_lens = [len(w) for w in words[:-1]]
                ctx_mean_len = np.mean(ctx_lens)
                ctx_std_len = np.std(ctx_lens)
                out_dense[i, f] = ctx_mean_len / 10.0; f += 1
                out_dense[i, f] = ctx_std_len / 5.0; f += 1
            else:
                f += 2

            onset_c = 0.0; coda_c = 0.0
            if trig_len >= 2:
                onset_c = 1.0 if trigger[0] in CONSONANTS else 0.0
                coda_c = 1.0 if trigger[-1] in CONSONANTS else 0.0
                out_dense[i, f] = onset_c; f += 1
                out_dense[i, f] = coda_c; f += 1
            else:
                f += 2

            for j in range(min(6, trig_len)):
                out_dense[i, f + j] = 1.0 if trigger[j] in CONSONANTS else 0.0
            f += 6

            char_diversity = len(set(trigger)) / (trig_len + 1e-8)
            out_dense[i, f] = char_diversity; f += 1

            trig_hash_simple = sum(int(c) * (31 ** idx) for idx, c in enumerate(trigger)) & 0x7FFFFFFF
            repeated = 0
            for w in words[:-1]:
                wh = sum(int(c) * (31 ** idx) for idx, c in enumerate(w)) & 0x7FFFFFFF
                if wh == trig_hash_simple and len(w) == trig_len:
                    repeated = 1; break
            out_dense[i, f] = repeated; f += 1

            for j in range(min(3, trig_len)):
                c = trigger[-(j+1)]
                out_dense[i, f + j] = 0.5 if c in VOWELS else (1.0 if c in CONSONANTS else 0.0)
            f += 3

            n_punct = sum(1 for c in trigger if c >= 39 or c == 1)
            out_dense[i, f] = n_punct / (trig_len + 1e-8); f += 1

            last_punct_dist = len(nonpad)
            for j in range(len(nonpad) - trig_len - 1, -1, -1):
                if nonpad[j] >= 39 or nonpad[j] == 1:
                    last_punct_dist = len(nonpad) - trig_len - j; break
            sent_pos = last_punct_dist / SEQ_LEN
            out_dense[i, f] = sent_pos; f += 1

            if n_words >= 2:
                prev = words[-2]
                out_dense[i, f] = _shared_chars(trigger, prev); f += 1
                out_dense[i, f] = _shared_bigrams(trigger, prev); f += 1
                out_dense[i, f] = 1.0 if (len(prev) > 0 and trigger[0] == prev[0]) else 0.0; f += 1
                out_dense[i, f] = 1.0 if (len(prev) > 0 and trigger[-1] == prev[-1]) else 0.0; f += 1
                out_dense[i, f] = abs(trig_len - len(prev)) / 10.0; f += 1
                out_dense[i, f] = trig_len / (len(prev) + 1e-8); f += 1
            else:
                f += 6

            if n_words >= 3:
                prev2 = words[-3]
                out_dense[i, f] = _shared_chars(trigger, prev2); f += 1
                out_dense[i, f] = _shared_bigrams(trigger, prev2); f += 1
                out_dense[i, f] = 1.0 if (len(prev2) > 0 and trigger[0] == prev2[0]) else 0.0; f += 1
            else:
                f += 3

            if n_words > 1:
                sim_sum = sum(_shared_chars(trigger, w) for w in words[:-1])
                out_dense[i, f] = sim_sum / (n_words - 1); f += 1
            else:
                f += 1

            if ctx_mean_len > 0:
                out_dense[i, f] = (trig_len - ctx_mean_len) / 5.0; f += 1
                z = abs(trig_len - ctx_mean_len) / (ctx_std_len + 1e-8) if ctx_std_len > 0.5 else 0.0
                out_dense[i, f] = min(z, 3.0) / 3.0; f += 1
            else:
                f += 2

            out_dense[i, f] = trig_len_norm ** 2; f += 1
            out_dense[i, f] = syl_norm ** 2; f += 1
            out_dense[i, f] = char_diversity ** 2; f += 1
            out_dense[i, f] = cluster_norm ** 2; f += 1
            out_dense[i, f] = sent_pos ** 2; f += 1

            syl_density = syllables / (trig_len + 1e-8)
            out_dense[i, f] = is_function * wc_norm; f += 1
            out_dense[i, f] = trig_len_norm * syl_density; f += 1
            out_dense[i, f] = char_diversity * trig_len_norm; f += 1
            out_dense[i, f] = onset_c * coda_c; f += 1
            out_dense[i, f] = is_function * float(repeated); f += 1
            out_dense[i, f] = cluster_norm * trig_len_norm; f += 1
            out_dense[i, f] = sent_pos * is_function; f += 1
            out_dense[i, f] = sent_pos * trig_len_norm; f += 1
            out_dense[i, f] = vowel_ratio * trig_len_norm; f += 1
            out_dense[i, f] = cons_ratio * cluster_norm; f += 1

            if n_words >= 3:
                recent = [len(w) for w in words[-min(5, n_words):]]
                diffs = [recent[k+1] - recent[k] for k in range(len(recent)-1)]
                out_dense[i, f] = np.mean(np.abs(diffs)) / 5.0; f += 1
                sign_changes = sum(1 for k in range(len(diffs)-1) if diffs[k]*diffs[k+1] < 0)
                out_dense[i, f] = sign_changes / (len(diffs) + 1e-8); f += 1
            else:
                f += 2

            if trig_len >= 3:
                trig_suffix = (trigger[-2], trigger[-1])
                suffix_match = sum(1 for w in words[:-1] if len(w) >= 2 and (w[-2], w[-1]) == trig_suffix)
                out_dense[i, f] = suffix_match / (n_words + 1e-8); f += 1
            else:
                f += 1

            words_since_punct = 0
            for w in reversed(words[:-1]):
                if any(c >= 39 or c == 1 for c in w): break
                words_since_punct += 1
            out_dense[i, f] = words_since_punct / 10.0; f += 1

            key_feats = [trig_len_norm, syl_norm, vowel_ratio, cons_ratio,
                         cluster_norm, char_diversity, is_function, sent_pos,
                         onset_c, coda_c, wc_norm, float(repeated)]
            len_hist = np.zeros(8, dtype=np.float32)
            for w in words[:-1]:
                bin_idx = min(len(w) - 1, 7)
                len_hist[bin_idx] += 1
            if n_words > 1:
                len_hist /= (n_words - 1)
            for hi in range(8):
                if f < D_DENSE:
                    out_dense[i, f] = len_hist[hi]; f += 1
            trig_bin = min(trig_len - 1, 7)
            if f < D_DENSE:
                out_dense[i, f] = len_hist[trig_bin]; f += 1
            for ki in range(len(key_feats)):
                for kj in range(ki + 1, len(key_feats)):
                    if f < D_DENSE:
                        out_dense[i, f] = key_feats[ki] * key_feats[kj]; f += 1

        # L2 normalize hash banks
        for arr in [out_trig, out_ctx, out_ctx_sharp, out_ctx_vs, out_trans]:
            norms = np.linalg.norm(arr, axis=1, keepdims=True) + 1e-8
            arr /= norms
        # Normalize embedding features
        norms = np.linalg.norm(out_embed, axis=1, keepdims=True) + 1e-8
        out_embed /= norms

        # Scale banks
        out_trig *= 1.5
        out_ctx_sharp *= 0.6
        out_ctx_vs *= 0.4
        out_trans *= 0.3

        # Bilinear trigger×context interaction: project both to 64D, element-wise multiply
        trig_proj = out_trig @ PROJ_TRIG  # (N, 64)
        ctx_proj = out_ctx @ PROJ_CTX      # (N, 64)
        out_bilinear = trig_proj * ctx_proj  # element-wise product
        # Normalize
        bi_norms = np.linalg.norm(out_bilinear, axis=1, keepdims=True) + 1e-8
        out_bilinear /= bi_norms
        out_bilinear *= 0.3  # low scale

        # NEW: vsharp × embed bilinear (prev-word identity × trigger phonology)
        # Project vsharp (256D) and embed (192D) to 32D each
        vs_proj = out_ctx_vs[:, :32]  # use first 32 dims of normalized vsharp as simple projection
        emb_proj = out_embed[:, :32]   # use first 32 dims of normalized embed
        out_vs_emb = vs_proj * emb_proj
        vsemb_norms = np.linalg.norm(out_vs_emb, axis=1, keepdims=True) + 1e-8
        out_vs_emb /= vsemb_norms
        out_vs_emb *= 0.2

        # Additional: sharp-context × embed (recent context words × trigger phonology)
        sharp_proj = out_ctx_sharp[:, :32]
        emb_proj2 = out_embed[:, 32:64]  # use DIFFERENT embed dims (max-pool view)
        out_sharp_emb = sharp_proj * emb_proj2
        se_norms = np.linalg.norm(out_sharp_emb, axis=1, keepdims=True) + 1e-8
        out_sharp_emb /= se_norms
        out_sharp_emb *= 0.15  # very low scale

        out = np.concatenate([out_trig, out_ctx, out_ctx_sharp, out_ctx_vs,
                              out_embed, out_dense, out_trans, out_bilinear, out_vs_emb, out_sharp_emb,
                              out_syncat], axis=1)
        return torch.tensor(out, dtype=torch.float32, device=device)


MODEL = Model()
